    /** Encrypted proposal binds actor/token, connection-wide revision and expiry. */
    private function seal(Request $request, string $purpose, array $data): string
    {
        return Crypt::encryptString(json_encode(['actor' => $request->user()->id, 'token' => Access::tokenHash($request),
            'connection' => $request->route('connection')->id, 'revision' => Input::etag($request), 'purpose' => $purpose,
            'expires' => now()->addMinutes(10)->timestamp, 'data' => $data], JSON_THROW_ON_ERROR));
    }

    private function open(Request $request, string $purpose): array
    {
        $request->validate(['preview_token' => 'required|string|max:500000']);
        try {
            $value = json_decode(Crypt::decryptString((string) $request->string('preview_token')), true, 512, JSON_THROW_ON_ERROR);
        } catch (\Throwable) {
            abort(422, 'Invalid preview token.');
        }
        abort_unless(($value['actor'] ?? null) === $request->user()->id && hash_equals($value['token'], Access::tokenHash($request))
            && $value['connection'] === $request->route('connection')->id && $value['purpose'] === $purpose, 403, 'Preview belongs to another target or actor.');
        abort_unless($value['expires'] >= now()->timestamp && hash_equals($value['revision'], Input::etag($request)), 409, 'Preview expired or target changed.');

        return $value['data'];
    }
